/* Alerts/settings design preview: in-memory preferences; no OS permissions or push jobs. */
const accountReminderDefaults={enabled:true,renewals:true,trials:true,timing:'3',customDays:4,time:'09:00'};
let accountReminders={...accountReminderDefaults};
let reminderSettingsOrigin='Alerts',pendingReminderSettings=null;
const alertGear=()=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9.5 3-.6 2.1-2 .9-2-.5-2.4 4.1L4 11.2v2l-1.5 1.6 2.4 4.1 2-.5 2 .9.6 2.1h5l.6-2.1 2-.9 2 .5 2.4-4.1-1.5-1.6v-2l1.5-1.6-2.4-4.1-2 .5-2-.9-.6-2.1z"/><circle cx="12" cy="12" r="3"/></svg>';
const alertBell=()=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4"/></svg>';
function alertsHeader(){return `<div class="head alerts-head"><h2>Alerts</h2><button class="alerts-settings-icon" data-open-reminder-settings aria-label="Reminder settings">${alertGear()}</button></div>`;}
function alertsScreen(){
 const blocked=current==='Alerts · notifications off',onlyTrial=current==='Alerts · trial',isEmpty=current==='Alerts · empty';
 const records=subscriptionListData(),find=(name)=>records.find(r=>r.name===name);
 const items=[{name:'Netflix',group:'Today',sent:'9:00 AM',message:'Renews today · USD 15.99',kind:'renewal'}, {name:'Spotify',group:'Yesterday',sent:'26 Oct · 9:00 AM',message:'Trial ends 31 Oct',kind:'trial'}, {name:'iCloud+',group:'Earlier',sent:'24 Oct · 9:00 AM',message:'Renews 30 Oct · USD 2.99',kind:'renewal'}].filter(r=>!onlyTrial||r.kind==='trial');
 const banner=blocked?`<div class="alerts-notice"><span class="alerts-notice-symbol">${alertBell()}</span><div><strong>Notifications are off</strong><p>Allow notifications so reminders can reach you.</p><button data-open-device-settings>Open settings ↗</button></div></div>`:!accountReminders.enabled?`<div class="alerts-notice"><span class="alerts-notice-symbol">${alertBell()}</span><div><strong>Push reminders are paused</strong><p>Your saved reminders and history are still here.</p><button data-open-reminder-settings>Manage reminders ›</button></div></div>`:'';
 const list=isEmpty?`<div class="alerts-empty">${mascotView({expression:'neutral',size:108,artworkScale:1.05,className:'alerts-empty-mascot'})}<h3>No alerts yet</h3><p>Your sent renewal and trial reminders will appear here.</p><button class="alerts-empty-action" data-open-reminder-settings>${alertGear()}<span>Manage reminders</span></button></div>`: ['Today','Yesterday','Earlier'].map(group=>{const rows=items.filter(r=>r.group===group);return rows.length?`<section class="alerts-group" aria-label="${group}"><div class="alerts-group-heading"><h3>${group}</h3><span>${rows.length}</span></div><div class="alerts-rows">${rows.map(r=>{const record=find(r.name);return `<button class="alert-row" data-alert-record="${escape(record?.id||'')}" aria-label="${escape(r.name+', '+r.message+', sent '+r.sent)}"><span class="avatar">${platformLogo(r.name)}</span><span class="alert-copy"><strong>${r.name}</strong><span class="alert-message ${r.kind==='trial'?'status-trial':''}">${r.message}</span><small>${r.sent}</small></span><span class="alert-row-chevron" aria-hidden="true">›</span></button>`;}).join('')}</div></section>`:'';}).join('');
 return `<div class="alerts-layout">${alertsHeader()}<p class="alerts-intro">Your renewal and trial reminders,<br>in one place.</p>${banner}${list}${!isEmpty?'<p class="alerts-history-note">Only sent reminders appear here.</p>':''}</div>`;
}
function reminderToggle(name,label,copy,value,master=false){return `<label class="account-reminder-toggle"><span><strong>${label}</strong><small>${copy}</small></span><input type="checkbox" role="switch" name="${name}" aria-label="${label}" ${value?'checked':''} ${!master&&!accountReminders.enabled?'disabled':''}></label>`;}
function reminderSettingsScreen(){
 const p=accountReminders,blocked=reminderSettingsOrigin==='Alerts · notifications off',zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Device timezone';
 return `<div class="reminder-settings-layout"><div class="head reminder-settings-head">${backButton({attributes:`data-reminder-settings-back`,label:"Back to Alerts",className:""})}<h2>Reminder settings</h2></div><p class="reminder-settings-intro">A little heads-up, on your terms.</p><form id="account-reminders-form" data-account-reminders novalidate><div class="reminder-settings-group">${reminderToggle('enabled','Push reminders','Pause or resume all push reminders.',p.enabled,true)}</div><h3 class="settings-group-label">WHAT TO REMIND YOU ABOUT</h3><div class="reminder-settings-group">${reminderToggle('renewals','Renewals','Before your next subscription charge.',p.renewals)}${reminderToggle('trials','Trials ending','Before a free trial comes to an end.',p.trials)}</div><h3 class="settings-group-label">YOUR DEFAULTS</h3><fieldset class="reminder-defaults" data-reminder-defaults ${!p.enabled?'disabled':''}><legend class="sr-only">Default reminder timing</legend>${selectField({label:'Remind me',name:'timing',value:p.timing,options:[{value:'off',label:'Off'},{value:'daily',label:'Daily for the last 3 days'},...[1,2,3,5,7,10,20].map(days=>({value:String(days),label:days+' day'+(days===1?'':'s')+' before'})),{value:'custom',label:'Custom days'}]})}<div data-global-custom ${p.timing==='custom'?'':'hidden'}><label for="account-reminder-custom">Days before the event<input id="account-reminder-custom" type="number" name="customDays" min="1" max="365" step="1" value="${p.customDays}" aria-describedby="account-reminder-custom-error"></label><p id="account-reminder-custom-error" class="field-error" role="alert" hidden></p></div><label class="reminder-time-label" for="account-reminder-time">Reminder time<input id="account-reminder-time" type="time" name="time" value="${p.time}" required aria-describedby="account-reminder-time-error"></label><p id="account-reminder-time-error" class="field-error" role="alert" hidden></p><p class="reminder-timezone">Local time · ${escape(zone.replace(/_/g,' '))}</p>${selectField({label:'Apply default timing to',name:'scope',value:'new',options:[{value:'new',label:'New subscriptions only'},{value:'existing',label:'Existing subscriptions too'}]})}<p class="settings-default-note">Custom subscription reminders stay as you set them.</p></fieldset><div class="device-notification-status"><span>${alertBell()}</span><div><strong>Device notifications</strong><small>${blocked?'Off · permission needed':'Allowed on this device'}</small></div><button type="button" data-open-device-settings aria-label="Open device notification settings">${blocked?'Enable':'Manage'} ↗</button></div></form><div class="reminder-settings-footer"><button class="primary" type="submit" form="account-reminders-form">Save settings</button><p>Applies to future reminders. Your history stays.</p></div></div>`;
}
function readAccountReminderForm(form){return {enabled:form.elements.enabled.checked,renewals:form.elements.renewals.checked,trials:form.elements.trials.checked,timing:form.elements.timing.value,customDays:Number(form.elements.customDays.value),time:form.elements.time.value};}
function accountReminderPreference(settings){return settings.timing==='off'?{mode:'off',days:0}:settings.timing==='daily'?{mode:'daily',days:3}:{mode:'once',days:settings.timing==='custom'?settings.customDays:Number(settings.timing)};}
function reminderApplyRecords(preserveCustom=true){return subscriptionListData().filter(r=>!['Cancelled','Expired','Deleted'].includes(r.status)&&!r.trialEnded&&(!preserveCustom||!reminderPreferences.has(r.id)));}
function finishReminderSettings(settings,applyExisting=false,preserveCustom=true){
 if(applyExisting){const pref=accountReminderPreference(settings);reminderApplyRecords(preserveCustom).forEach(r=>reminderPreferences.set(r.id,{...pref}));}
 accountReminders={...settings};pendingReminderSettings=null;go(reminderSettingsOrigin);toast('Reminder settings saved.');
}
function closeReminderApply(phone){phone.querySelector('.reminder-apply-overlay')?.remove();phone.querySelectorAll('[data-reminder-apply-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-reminder-apply-inert');});phone.querySelector('[name="scope"]')?.parentElement.querySelector('[data-select-trigger]')?.focus();pendingReminderSettings=null;}
function openReminderApply(form,settings){const phone=form.closest('.phone'),overlay=document.createElement('div');pendingReminderSettings=settings;overlay.className='reminder-apply-overlay';overlay.innerHTML=`<div class="reminder-apply-shade" data-close-reminder-apply></div><section class="reminder-apply-dialog" role="dialog" aria-modal="true" aria-labelledby="reminder-apply-title"><header><h3 id="reminder-apply-title">Update existing reminders?</h3><button data-close-reminder-apply aria-label="Close apply reminders">×</button></header><p>Use your new default timing for the subscriptions below. Dates that have passed won’t send a late reminder.</p><label class="reminder-preserve"><input type="checkbox" data-preserve-custom checked><span>Keep custom reminders<small>Preserve settings changed on individual subscriptions.</small></span></label><p class="reminder-apply-count" role="status">${reminderApplyRecords().length} subscriptions will update</p><div class="reminder-apply-actions"><button class="secondary" data-close-reminder-apply>Go back</button><button class="primary" data-confirm-reminder-apply>Update reminders</button></div></section>`;phone.append(overlay);[...phone.children].filter(el=>el!==overlay&&!el.inert).forEach(el=>{el.inert=true;el.dataset.reminderApplyInert='true';});overlay.querySelector('button').focus();}
document.addEventListener('click',event=>{
 const open=event.target.closest('[data-open-reminder-settings]'),back=event.target.closest('[data-reminder-settings-back]'),device=event.target.closest('[data-open-device-settings]'),record=event.target.closest('[data-alert-record]'),close=event.target.closest('[data-close-reminder-apply]'),confirm=event.target.closest('[data-confirm-reminder-apply]');
 if(open){reminderSettingsOrigin=current;go('Reminder settings');}
 else if(back)go(reminderSettingsOrigin);
 else if(device)toast('Open your phone’s Settings → Notifications → Renewless to manage permissions.');
 else if(record){const r=subscriptionListData().find(r=>r.id===record.dataset.alertRecord);if(r){state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');}else toast('This subscription is no longer available.');}
 else if(close)closeReminderApply(close.closest('.phone'));
 else if(confirm&&pendingReminderSettings){const preserve=confirm.closest('.reminder-apply-overlay').querySelector('[data-preserve-custom]').checked;finishReminderSettings(pendingReminderSettings,true,preserve);}
});
document.addEventListener('change',event=>{
 const form=event.target.closest('[data-account-reminders]');if(form){if(event.target.name==='enabled'){const disabled=!event.target.checked;form.querySelectorAll('[name="renewals"],[name="trials"],[data-reminder-defaults]').forEach(el=>el.disabled=disabled);syncSelectControls();}if(event.target.name==='timing')form.querySelector('[data-global-custom]').hidden=event.target.value!=='custom';}
 if(event.target.matches('[data-preserve-custom]'))event.target.closest('.reminder-apply-dialog').querySelector('.reminder-apply-count').textContent=reminderApplyRecords(event.target.checked).length+' subscriptions will update';
});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-account-reminders]');if(!form)return;event.preventDefault();const settings=readAccountReminderForm(form);form.querySelectorAll('.field-error').forEach(el=>el.hidden=true);form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
 if(settings.enabled&&(!/^\d{2}:\d{2}$/.test(settings.time)||(settings.timing==='custom'&&(!Number.isInteger(settings.customDays)||settings.customDays<1||settings.customDays>365)))){const field=form.elements[settings.time?'customDays':'time'],error=form.querySelector(settings.time?'#account-reminder-custom-error':'#account-reminder-time-error');error.textContent=settings.time?'Enter a whole number from 1 to 365 days.':'Choose a reminder time.';error.hidden=false;field.setAttribute('aria-invalid','true');field.focus();return;}
 if(settings.enabled&&form.elements.scope.value==='existing')openReminderApply(form,settings);else finishReminderSettings(settings);
});
document.addEventListener('keydown',event=>{const overlay=document.querySelector('.reminder-apply-overlay');if(!overlay)return;if(event.key==='Escape'){event.preventDefault();closeReminderApply(overlay.closest('.phone'));}else if(event.key==='Tab'){const items=[...overlay.querySelectorAll('button,input')],first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

function resetAccountReminders(){accountReminders={...accountReminderDefaults};pendingReminderSettings=null;reminderSettingsOrigin='Alerts';}
